import math

def torus_report(p: int, q: int) -> dict[str, int | bool]:
    product=p*q
    common=math.gcd(p,q)
    multiple=abs(product)//common if product else 0
    return {"p":p,"q":q,"charge":product,"gcd":common,"lcm":multiple,
            "coprime":common==1,"charge_equals_lcm":product==multiple}

for pair in [(2,3),(3,5),(2,4),(4,9)]:
    print(torus_report(*pair))

