from __future__ import annotations
import cmath, math
from typing import Sequence

def discrete_winding(samples: Sequence[complex], tolerance: float = 1e-12) -> float:
    if len(samples) < 4 or min(map(abs, samples)) <= tolerance:
        raise ValueError("need at least four nonzero samples")
    increments=(cmath.phase(samples[(j+1)%len(samples)]*samples[j].conjugate())
                for j in range(len(samples)))
    return math.fsum(increments)/(2*math.pi)

from __future__ import annotations
import cmath, math
from typing import Sequence

def endpoint_defect(samples: Sequence[complex], zero_tolerance: float = 1e-12) -> complex:
    if len(samples)<4 or min(map(abs,samples))<=zero_tolerance:
        raise ValueError("non-vanishing samples required")
    phase=sum(cmath.phase(samples[(j+1)%len(samples)]*samples[j].conjugate())
              for j in range(len(samples)))
    log_modulus=math.log(abs(samples[0]))-math.log(abs(samples[0]))
    return complex(log_modulus, phase)

def closes(samples: Sequence[complex], tolerance: float=1e-8) -> bool:
    return abs(endpoint_defect(samples)) < tolerance

